(()=>{"use strict";const body=document.querySelector("#project-body"),search=document.querySelector("#search"),status=document.querySelector("#status"),sort=document.querySelector("#sort"),count=document.querySelector("#result-count"),total=document.querySelector("#total"),completed=document.querySelector("#completed"),active=document.querySelector("#active"),budget=document.querySelector("#budget"),health=document.querySelector("#health"),chart=document.querySelector("#chart"),menu=document.querySelector(".menu-toggle"),nav=document.querySelector("#navigation");let projects=[];const money=n=>new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:0}).format(n);function render(list){if(!body)return;count.textContent=`${list.length} of ${projects.length} projects`;body.innerHTML=list.length?list.map(p=>`<tr><td>${p.name}</td><td>${p.owner}</td><td>${p.category}</td><td><span class="pill">${p.status}</span></td><td><div class="progress"><span>${p.progress}%</span><div class="progress-bar" aria-hidden="true"><i style="width:${p.progress}%"></i></div></div></td><td>${money(p.budget)}</td></tr>`).join(""):`<tr><td colspan="6">No projects match the selected filters.</td></tr>`;renderChart(list)}function renderChart(list){if(!chart)return;chart.innerHTML=list.length?list.map(p=>`<div class="bar-row"><span>${p.name}</span><div class="bar" role="img" aria-label="${p.name}: ${p.progress}% complete"><i style="width:${p.progress}%"></i></div><strong>${p.progress}%</strong></div>`).join(""):`<p>No chart data available.</p>`}function update(){const q=(search?.value||"").toLowerCase(),s=status?.value||"All";let list=projects.filter(p=>(s==="All"||p.status===s)&&(`${p.name} ${p.owner} ${p.category}`.toLowerCase().includes(q)));switch(sort?.value){case"name":list.sort((a,b)=>a.name.localeCompare(b.name));break;case"budget-desc":list.sort((a,b)=>b.budget-a.budget);break;case"progress-asc":list.sort((a,b)=>a.progress-b.progress);break;default:list.sort((a,b)=>b.progress-a.progress)}render(list)}function setup(){if(!projects.length)return;total.textContent=projects.length;completed.textContent=projects.filter(p=>p.status==="Completed").length;active.textContent=projects.filter(p=>p.status==="In Progress").length;budget.textContent=money(projects.reduce((a,p)=>a+p.budget,0));health.textContent=Math.round(projects.reduce((a,p)=>a+p.progress,0)/projects.length)+"%";update()}[search,status,sort].forEach(el=>el?.addEventListener("input",update));menu?.addEventListener("click",()=>{const open=menu.getAttribute("aria-expanded")==="true";menu.setAttribute("aria-expanded",String(!open));nav?.classList.toggle("open",!open)});nav?.addEventListener("click",e=>{if(e.target.matches("a")){nav.classList.remove("open");menu?.setAttribute("aria-expanded","false")}});window.addEventListener("keydown",e=>{if(e.key==="Escape"){nav?.classList.remove("open");menu?.setAttribute("aria-expanded","false")}});fetch("data.json").then(r=>{if(!r.ok)throw Error("Data request failed");return r.json()}).then(d=>{projects=Array.isArray(d)?d:[];setup()}).catch(()=>{if(body)body.innerHTML='<tr><td colspan="6">Unable to load project data. Please run the app through a local web server.</td></tr>';if(count)count.textContent="Data unavailable"})})();